// Source-exact discrete arclength rule: 16000 chord intervals on each side.
// Calculate once per side; binary interpolation is used for all catch vertices.
function r10bTrayArc(sign is number) returns array
{
    var lengths = [0];
    var previous = r10bTrayCurve(0 * radian);
    var total = 0;
    for (var i = 1; i <= 16000; i += 1)
