export function buildR10bTray(context is Context, id is Id, definition is map) returns Query
{
    // Required ValueWithUnits LENGTH parameters; never silently accept naked mm.
    var pitch = definition.catchPitch / millimeter;
    var height = definition.catchHeight / millimeter;
    var wall = definition.innerWallThickness / millimeter;
    if (pitch < 3 || pitch > 6 || height < 0.25 || height > 1 || wall < 3.2 || wall > 5.2)
        throw regenError("T01 interior parameters outside allowed ranges", ["catchPitch","catchHeight","innerWallThickness"]);
    var body = r10bTrayPrism(context, id + "Outer", -91.25, 182.5, R10B_TRAY_OUTER);
    var cavity = r10bTrayPrism(context, id + "Cavity", -88.1, 176.2, r10bTrayInside(pitch,height,wall));
    opBoolean(context, id + "Hollow", { "targets" : body, "tools" : cavity,
        "operationType" : BooleanOperationType.SUBTRACTION });
    body = qBodyType(qUnion([body, qCreatedBy(id + "Hollow", EntityType.BODY)]), BodyType.SOLID);
    // Final interface: no spigot bores. Left has three M3 countersunk holes on
    // PCD 11 at 0/120/240 degrees; right retains its four-hole pattern.
    var leftAngles = [0, 120, 240];
    for (var i in [0, 1, 2])
    {
        var angle = leftAngles[i] * degree;
        var yy = 100 + 5.5 * cos(angle);
        var zz = 210 + 5.5 * sin(angle);
        body = r10bTrayBore(context,id+("LeftBore"~i),body,-92.05,-87.05,yy,zz,1.7);
        body = r10bTrayCountersink(context,id+("LeftSink"~i),body,-89.85,-88.09,yy,zz,1.3,3.06);
    }
    var k = 0;
    for (var dy in [-6.718,6.718])
        for (var dz in [-6.718,6.718])
        {
            var holeId = id + ("RightMount" ~ k);
            body = r10bTrayBore(context,holeId+"Bore",body,87.05,92.05,100+dy,210+dz,1.7);
            body = r10bTrayCountersink(context,holeId+"Sink",body,88.09,89.85,100+dy,210+dz,3.06,1.3);
            k += 1;
        }
    var result = qBodyType(body, BodyType.SOLID);
    if (size(evaluateQuery(context,result)) != 1)
        throw regenError("T01 must regenerate as exactly one solid");
    setProperty(context, { "entities" : result, "propertyType" : PropertyType.NAME,
        "value" : "T01 R10b frozen shell live interior" });
    setProperty(context, { "entities" : result, "propertyType" : PropertyType.APPEARANCE,
        "value" : color(0.8,0.83,0.82) });
    return result;
}

