// Protected source crest: original +X-high transverse direction, high point (90.2,4,121.03) rail.
// Wall stays 4mm. All K05/K10/K15/K20 variants are nose-free.
// Legacy nose parameters remain for stored feature compatibility, not geometry.
export enum R10bEdgeAngle {
 annotation {"Name":"5 degrees"} K05,
 annotation {"Name":"10 degrees"} K10,
 annotation {"Name":"15 degrees"} K15,
