function buildTransferEdge(context is Context,id is Id,angle is number,noseLength is ValueWithUnits) returns Query {
 var before=qUnion(evaluateQuery(context,qAllModifiableSolidBodies()));
 var b=block(context,id+"wall",vector(-93.3,0,48),vector(93.3,4,150));
 var k=tan(angle*degree);
