 var apronNormalWall=2.1; // Sloped faces: >=2mm normal, with 0.1mm reserve.
 var apronRootY=3;
 var apronGuideWidth=8.5;
 var apronFloorWidth=6; // Assumed feed-item scale, not a measured part size.
 var apronBlendWidth=12;
 var apronGuideLead=0.5;
 var c25=cos(25*degree);
 var s25=sin(25*degree);
 var apronLeftZ=121.03+k*(-93.3-90.2);
 var apronDeficit=apronTargetY-(4*c25+s25*apronLeftZ);
 // K05 already clears Y=44 everywhere; never create a degenerate apron.
 if(apronDeficit>0) {
  if(apronDeficit<=apronGuideLead)throw regenError("Apron guide requires more discharge deficit");
  var apronFloorLeft=-93.3+apronGuideWidth;
  var apronFloorRight=apronFloorLeft+apronFloorWidth;
  var apronBlendEnd=apronFloorRight+apronBlendWidth;
  // dX/dY=a/(sin25+cos25*tan5); reach the flat floor by Y=43.5.
  // K10 gets a deeper channel via this SAME formula, not a longer lip.
  var apronDrop=k*apronGuideWidth+apronGuideWidth^2*(s25+c25*apronSlope)/(apronDeficit-apronGuideLead);
  var apronFloorZ=121.03+k*(apronFloorLeft-90.2)-apronDrop;
  var apronNodes=[vector(-93.3,apronLeftZ),vector(apronFloorLeft,apronFloorZ),
   vector(apronFloorRight,apronFloorZ),vector(apronBlendEnd,121.03+k*(apronBlendEnd-90.2)),
